const fs = require('fs');

function normalize(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const data = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
const P = normalize(data[0].trim());
const A = normalize(data[1].trim());

const count = {};

for (const ch of P) {
  count[ch] = (count[ch] || 0) + 1;
}

for (const ch of A) {
  if (ch === '*') continue;
  if (!count[ch]) {
    console.log('N');
    process.exit(0);
  }
  count[ch]--;
}

console.log('S');
